import{_ as a,c as n,o as i,a2 as e}from"./chunks/framework.PGES7OoM.js";const k=JSON.parse('{"title":"watchOperations","description":"Subscribe with immediate delivery; stale async reads cannot overwrite a newer account or revision.","frontmatter":{"editLink":false,"rawMarkdown":"# watchOperations\\n\\nSubscribe with immediate delivery; stale async reads cannot overwrite a newer account or revision.\\n\\n## Import\\n\\n```ts\\nimport { watchOperations } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = watchOperations({ onChange, onError, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction watchOperations(parameters: WatchOperationsParameters): () => void\\n```\\n\\n## Returns\\n\\n`() => void`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nThe account whose operations are watched. Defaults to the active account.\\n\\n```ts\\nconst result = watchOperations({\\n  accountId, // [!code focus]\\n  onChange,\\n  onError,\\n});\\n```\\n\\n### `onChange`\\n\\n- **Type:** `(operations: OperationSnapshot[]) => void`\\n- **Required:** yes\\n\\nCalled immediately and on every change with the current operation snapshots.\\n\\n```ts\\nconst result = watchOperations({\\n  onChange, // [!code focus]\\n  onError,\\n});\\n```\\n\\n### `onError`\\n\\n- **Type:** `(error: unknown) => void`\\n- **Required:** yes\\n\\nCalled when a background read fails.\\n\\n```ts\\nconst result = watchOperations({\\n  onChange,\\n  onError, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nStops the subscription; the returned function does the same.\\n\\n```ts\\nconst result = watchOperations({\\n  onChange,\\n  onError,\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = watchOperations({\\n  onChange,\\n  onError,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/watchOperations.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/watchOperations.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/watchOperations.md","rawMarkdownTitle":"watchOperations","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/watchOperations.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"watchOperations"},"relativePath":"sdk/actions/views/watchOperations.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),t={name:"sdk/actions/views/watchOperations.md"};function r(o,s,h,l,p,c){return i(),n("div",null,[...s[0]||(s[0]=[e("",38)])])}const g=a(t,[["render",r]]);export{k as __pageData,g as default};
